-- Invalidate the board's task summary when any of its source data changes.
CREATE TABLE IF NOT EXISTS board_task_revision (id INTEGER PRIMARY KEY CHECK (id=1), revision TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS board_revision_tasks_insert AFTER INSERT ON tasks BEGIN UPDATE board_task_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS board_revision_tasks_update AFTER UPDATE ON tasks BEGIN UPDATE board_task_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS board_revision_tasks_delete AFTER DELETE ON tasks BEGIN UPDATE board_task_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
